35	  }
36	
37	  return (
38	    <a
39	      href={url}
40	      target="_blank"
41	      rel="noopener noreferrer"
42	      className={cn(
43	        "group my-0 mb-2 flex w-full max-w-full overflow-hidden rounded-md border border-border bg-muted/20 text-foreground no-underline transition-colors",
44	        "hover:border-primary/35 hover:bg-accent/20",
45	      )}
46	    >
47	      <span className="flex min-w-0 flex-1 flex-col gap-0.5 px-2.5 py-2 sm:gap-1 sm:px-3 sm:py-2.5">
48	        {hostname && <span className="truncate text-[11px] leading-4 text-muted-foreground sm:text-xs">{hostname}</span>}
49	        {title && <span className="line-clamp-2 text-sm font-medium leading-5 text-foreground">{title}</span>}
50	        {description && <span className="line-clamp-1 text-xs leading-4 text-muted-foreground sm:line-clamp-2">{description}</span>}
51	      </span>
52	      {image && !imageFailed && (
53	        <span className="flex w-24 shrink-0 items-center border-l border-border/70 bg-muted/40 sm:w-40">
54	          <span className="aspect-[1.91/1] w-full overflow-hidden">
55	            <img
56	              src={image}
57	              alt=""
58	              className="h-full w-full object-cover transition-transform duration-200 group-hover:scale-[1.01]"
59	              loading="lazy"
60	              decoding="async"
61	              onError={() => setImageFailed(true)}
62	            />
63	          </span>
64	        </span>
65	      )}
66	    </a>
67	  );
68	};
